CREATE TABLE cmdb_ire_external_identities (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, source_id BIGINT UNSIGNED NOT NULL, scope_key VARCHAR(255) NOT NULL DEFAULT '', source_native_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, ci_id BIGINT UNSIGNED NOT NULL, first_seen_at DATETIME(6) NOT NULL, last_seen_at DATETIME(6) NOT NULL, last_seen_run_type VARCHAR(24) NOT NULL DEFAULT 'OBSERVATION', last_seen_run_id BIGINT UNSIGNED NULL, stale_since DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY cmdb_ire_external_key(tenant_id,source_id,scope_key,source_native_key), UNIQUE KEY cmdb_ire_external_tenant_id(tenant_id,id), KEY cmdb_ire_external_ci(tenant_id,ci_id,id), KEY cmdb_ire_external_stale(tenant_id,source_id,scope_key,stale_since), CONSTRAINT cmdb_ire_external_source FOREIGN KEY(tenant_id,source_id) REFERENCES cmdb_ire_sources(tenant_id,id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_external_ci FOREIGN KEY(tenant_id,ci_id) REFERENCES cmdb_cis(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
